const email = $input.first().json;
const required = ['messageId', 'from', 'subject', 'body'];
const missing = required.filter((field) => email[field] === undefined || email[field] === null || String(email[field]).trim() === '');
const body = String(email.body ?? '').replace(/\s+/g, ' ').trim();
const subject = String(email.subject ?? '').replace(/\s+/g, ' ').trim();
return [{ json: { ...email, subject, body, bodyLength: body.length, missingFields: missing, inputValid: missing.length === 0 && body.length >= 10 } }];

