const email = $items('Normalize Email')[0].json;
const raw = String($input.first().json.text ?? $input.first().json.response ?? '');
let parsed;
try {
  const cleaned = raw.replace(/^```json\s*/i, '').replace(/\s*```$/i, '').trim();
  parsed = JSON.parse(cleaned);
} catch (error) {
  parsed = {
    category: 'other',
    priority: 'medium',
    sentiment: 'neutral',
    customerRequest: 'The model did not return valid structured output.',
    suggestedReply: 'Thanks for reaching out. We received your message and will review it before replying.',
    needsHumanReview: true,
    reviewReasons: ['Invalid structured AI output']
  };
}
const reviewReasons = Array.isArray(parsed.reviewReasons) ? parsed.reviewReasons : [];
if (!email.inputValid) reviewReasons.push('Input email is missing required fields or has an unusually short body');
const needsHumanReview = Boolean(parsed.needsHumanReview) || reviewReasons.length > 0;
return [{ json: { ...email, category: parsed.category ?? 'other', priority: parsed.priority ?? 'medium', sentiment: parsed.sentiment ?? 'neutral', customerRequest: parsed.customerRequest ?? '', suggestedReply: parsed.suggestedReply ?? '', needsHumanReview, reviewReasons, safetyNote: 'Draft only. No email was sent and no external service was called.' } }];
